/**
 * Accessibility Utilities
 * 
 * Helper functions and hooks for improving accessibility
 */

import { useEffect, useCallback, useRef } from 'react';

/**
 * Announce message to screen readers
 */
export function announceToScreenReader(message: string, priority: 'polite' | 'assertive' = 'polite') {
    const announcement = document.createElement('div');
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', priority);
    announcement.setAttribute('aria-atomic', 'true');
    announcement.className = 'sr-only'; // Screen reader only
    announcement.textContent = message;

    document.body.appendChild(announcement);

    // Remove after announcement
    setTimeout(() => {
        document.body.removeChild(announcement);
    }, 1000);
}

/**
 * Hook for keyboard navigation
 */
export function useKeyboardNavigation(
    onEnter?: () => void,
    onEscape?: () => void,
    onArrowKeys?: (direction: 'up' | 'down' | 'left' | 'right') => void
) {
    const handleKeyDown = useCallback((event: KeyboardEvent) => {
        switch (event.key) {
            case 'Enter':
                if (onEnter) {
                    event.preventDefault();
                    onEnter();
                }
                break;
            case 'Escape':
                if (onEscape) {
                    event.preventDefault();
                    onEscape();
                }
                break;
            case 'ArrowUp':
                if (onArrowKeys) {
                    event.preventDefault();
                    onArrowKeys('up');
                }
                break;
            case 'ArrowDown':
                if (onArrowKeys) {
                    event.preventDefault();
                    onArrowKeys('down');
                }
                break;
            case 'ArrowLeft':
                if (onArrowKeys) {
                    event.preventDefault();
                    onArrowKeys('left');
                }
                break;
            case 'ArrowRight':
                if (onArrowKeys) {
                    event.preventDefault();
                    onArrowKeys('right');
                }
                break;
        }
    }, [onEnter, onEscape, onArrowKeys]);

    useEffect(() => {
        document.addEventListener('keydown', handleKeyDown);
        return () => document.removeEventListener('keydown', handleKeyDown);
    }, [handleKeyDown]);
}

/**
 * Focus trap for modals and dialogs
 */
export function useFocusTrap(containerRef: React.RefObject<HTMLElement>, isActive: boolean) {
    useEffect(() => {
        if (!isActive || !containerRef.current) return;

        const container = containerRef.current;
        const focusableElements = container.querySelectorAll(
            'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );

        const firstElement = focusableElements[0] as HTMLElement;
        const lastElement = focusableElements[focusableElements.length - 1] as HTMLElement;

        const handleTabKey = (e: KeyboardEvent) => {
            if (e.key !== 'Tab') return;

            if (e.shiftKey) {
                if (document.activeElement === firstElement) {
                    e.preventDefault();
                    lastElement?.focus();
                }
            } else {
                if (document.activeElement === lastElement) {
                    e.preventDefault();
                    firstElement?.focus();
                }
            }
        };

        // Focus first element
        firstElement?.focus();

        document.addEventListener('keydown', handleTabKey);
        return () => document.removeEventListener('keydown', handleTabKey);
    }, [containerRef, isActive]);
}

/**
 * Skip navigation link component
 */
export function SkipNavLink({ href = '#main-content', children = 'Skip to main content' }: {
    href?: string;
    children?: React.ReactNode;
}) {
    return (
        <a
            href= { href }
    className = "sr-only focus:not-sr-only focus:fixed focus:top-4 focus:left-4 focus:z-50 focus:px-4 focus:py-2 focus:bg-primary focus:text-primary-foreground focus:rounded-md focus:outline-none focus:ring-2 focus:ring-ring"
        >
        { children }
        </a>
    );
}

/**
 * Live region for dynamic content updates
 */
export function useLiveRegion() {
    const regionRef = useRef<HTMLDivElement | null>(null);

    useEffect(() => {
        const region = document.createElement('div');
        region.setAttribute('role', 'status');
        region.setAttribute('aria-live', 'polite');
        region.setAttribute('aria-atomic', 'true');
        region.className = 'sr-only';
        document.body.appendChild(region);
        regionRef.current = region;

        return () => {
            if (regionRef.current) {
                document.body.removeChild(regionRef.current);
            }
        };
    }, []);

    const announce = useCallback((message: string) => {
        if (regionRef.current) {
            regionRef.current.textContent = message;
        }
    }, []);

    return { announce };
}

/**
 * Reduced motion preference hook
 */
export function usePrefersReducedMotion(): boolean {
    const [prefersReducedMotion, setPrefersReducedMotion] = React.useState(false);

    useEffect(() => {
        const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
        setPrefersReducedMotion(mediaQuery.matches);

        const handleChange = (e: MediaQueryListEvent) => {
            setPrefersReducedMotion(e.matches);
        };

        mediaQuery.addEventListener('change', handleChange);
        return () => mediaQuery.removeEventListener('change', handleChange);
    }, []);

    return prefersReducedMotion;
}

// Import React for the hook
import React from 'react';

/**
 * Deep Linking Support for Credential Wallet
 * 
 * Handles custom URL schemes and universal links for:
 * - Receiving credentials from issuers
 * - Opening specific credentials
 * - Initiating verification flows
 * 
 * URL Schemes:
 * - credverse://receive?token=<offer_id>
 * - credverse://credential/<credential_id>
 * - credverse://verify?token=<share_token>
 * - https://wallet.credverse.io/receive?token=<offer_id>
 */

export interface DeepLinkParams {
    action: 'receive' | 'credential' | 'verify' | 'connect' | 'unknown';
    token?: string;
    credentialId?: string;
    issuer?: string;
    redirectUrl?: string;
}

/**
 * Parse a deep link URL
 */
export function parseDeepLink(url: string): DeepLinkParams {
    try {
        // Handle custom scheme
        const normalized = url
            .replace('credverse://', 'https://app.credverse.io/')
            .replace('blockcred://', 'https://app.credverse.io/');

        const parsed = new URL(normalized);
        const pathname = parsed.pathname;
        const params = parsed.searchParams;

        // Receive credential offer
        if (pathname.includes('/receive') || params.has('offer')) {
            return {
                action: 'receive',
                token: params.get('token') || params.get('offer') || undefined,
                issuer: params.get('issuer') || undefined,
                redirectUrl: params.get('redirect') || undefined,
            };
        }

        // View specific credential
        if (pathname.match(/\/credential\/([\w-]+)/)) {
            const match = pathname.match(/\/credential\/([\w-]+)/);
            return {
                action: 'credential',
                credentialId: match?.[1],
            };
        }

        // Verify a shared credential
        if (pathname.includes('/verify')) {
            return {
                action: 'verify',
                token: params.get('token') || pathname.split('/').pop() || undefined,
            };
        }

        // Connect to DigiLocker or other service
        if (pathname.includes('/connect')) {
            return {
                action: 'connect',
                token: params.get('code') || undefined,
            };
        }

        return { action: 'unknown' };
    } catch {
        return { action: 'unknown' };
    }
}

/**
 * Generate a deep link for sharing
 */
export function generateDeepLink(
    action: 'receive' | 'verify' | 'credential',
    params: Record<string, string>
): { webUrl: string; appUrl: string } {
    const baseWeb = 'https://wallet.credverse.io';
    const baseApp = 'credverse://';

    const queryString = new URLSearchParams(params).toString();

    switch (action) {
        case 'receive':
            return {
                webUrl: `${baseWeb}/receive?${queryString}`,
                appUrl: `${baseApp}receive?${queryString}`,
            };
        case 'verify':
            return {
                webUrl: `${baseWeb}/verify/${params.token || ''}`,
                appUrl: `${baseApp}verify?token=${params.token || ''}`,
            };
        case 'credential':
            return {
                webUrl: `${baseWeb}/credential/${params.id || ''}`,
                appUrl: `${baseApp}credential/${params.id || ''}`,
            };
    }
}

/**
 * Hook to handle deep links on app load
 */
export function useDeepLinkHandler(handlers: {
    onReceive?: (token: string) => void;
    onCredential?: (id: string) => void;
    onVerify?: (token: string) => void;
    onConnect?: (code: string) => void;
}) {
    // Check URL on mount
    if (typeof window !== 'undefined') {
        const url = window.location.href;
        const params = parseDeepLink(url);

        switch (params.action) {
            case 'receive':
                if (params.token && handlers.onReceive) {
                    handlers.onReceive(params.token);
                }
                break;
            case 'credential':
                if (params.credentialId && handlers.onCredential) {
                    handlers.onCredential(params.credentialId);
                }
                break;
            case 'verify':
                if (params.token && handlers.onVerify) {
                    handlers.onVerify(params.token);
                }
                break;
            case 'connect':
                if (params.token && handlers.onConnect) {
                    handlers.onConnect(params.token);
                }
                break;
        }
    }
}

/**
 * Generate OID4VCI credential offer URL
 * Following OpenID for Verifiable Credential Issuance spec
 */
export function generateOID4VCIOfferUrl(params: {
    credentialOfferId: string;
    issuerUrl: string;
    credentialType: string;
}): string {
    const base = 'openid-credential-offer://';
    const offerParams = new URLSearchParams({
        credential_offer_uri: `${params.issuerUrl}/credential-offer/${params.credentialOfferId}`,
    });

    return `${base}?${offerParams.toString()}`;
}

/**
 * Parse OID4VP presentation request
 * Following OpenID for Verifiable Presentations spec
 */
export function parseOID4VPRequest(url: string): {
    responseUri: string;
    presentationDefinition: any;
    nonce: string;
} | null {
    try {
        const parsed = new URL(url.replace('openid-vc://', 'https://'));
        const params = parsed.searchParams;

        return {
            responseUri: params.get('response_uri') || '',
            presentationDefinition: JSON.parse(params.get('presentation_definition') || '{}'),
            nonce: params.get('nonce') || '',
        };
    } catch {
        return null;
    }
}

import { useState, useEffect } from "react";
import { useLocation, useSearch } from "wouter";
import { motion, AnimatePresence } from "framer-motion";
import { Sidebar } from "@/components/sidebar";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  CheckCircle2,
  Loader2,
  Shield,
  AlertCircle,
  FileText,
  Download,
  ExternalLink,
  Fingerprint,
  CreditCard,
  Car,
  GraduationCap,
  RefreshCw,
  LogOut
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";

interface DigiLockerDocument {
  uri: string;
  doctype: string;
  name: string;
  description: string;
  issuer: string;
  date: string;
}

const docTypeIcons: Record<string, any> = {
  ADHAR: Fingerprint,
  PAN: CreditCard,
  DRVLC: Car,
  CLASS10: GraduationCap,
  CLASS12: GraduationCap,
  DEGREE: GraduationCap,
};

export default function ConnectDigiLocker() {
  const [, setLocation] = useLocation();
  const searchString = useSearch();
  const searchParams = new URLSearchParams(searchString);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const [importing, setImporting] = useState<string | null>(null);

  // Check URL params for callback result
  useEffect(() => {
    const connected = searchParams.get('connected');
    const error = searchParams.get('error');

    if (connected === 'true') {
      toast({
        title: "DigiLocker Connected!",
        description: "Your account is now linked. You can import documents.",
        className: "bg-emerald-900/90 border-emerald-500/20 text-white",
      });
      queryClient.invalidateQueries({ queryKey: ['digilocker-status'] });
    }

    if (error) {
      toast({
        title: "Connection Failed",
        description: error,
        variant: "destructive",
      });
    }
  }, [searchParams]);

  // Check connection status
  const { data: statusData, isLoading: statusLoading } = useQuery({
    queryKey: ['digilocker-status'],
    queryFn: async () => {
      const res = await fetch('/api/digilocker/status?userId=1');
      return res.json();
    },
  });

  // Get available documents
  const { data: documentsData, isLoading: docsLoading } = useQuery({
    queryKey: ['digilocker-documents'],
    queryFn: async () => {
      const res = await fetch('/api/digilocker/documents?userId=1');
      return res.json();
    },
    enabled: statusData?.connected,
  });

  // Connect mutation
  const connectMutation = useMutation({
    mutationFn: async () => {
      const res = await fetch('/api/digilocker/connect', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: 1 }),
      });
      return res.json();
    },
    onSuccess: (data) => {
      if (data.requiresAuth) {
        // Redirect to DigiLocker OAuth
        window.location.href = data.authUrl;
      } else if (data.success) {
        toast({
          title: "DigiLocker Connected!",
          description: `${data.documentsImported} documents imported.`,
          className: "bg-emerald-900/90 border-emerald-500/20 text-white",
        });
        queryClient.invalidateQueries({ queryKey: ['digilocker-status'] });
        queryClient.invalidateQueries({ queryKey: ['digilocker-documents'] });
        queryClient.invalidateQueries({ queryKey: ['wallet-credentials'] });
      }
    },
    onError: () => {
      toast({
        title: "Connection Failed",
        description: "Could not connect to DigiLocker.",
        variant: "destructive",
      });
    },
  });

  // Import single document
  const importMutation = useMutation({
    mutationFn: async (doc: DigiLockerDocument) => {
      setImporting(doc.uri);
      const res = await fetch('/api/digilocker/import', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: 1,
          documentUri: doc.uri,
          documentType: doc.doctype,
          documentName: doc.name,
          issuer: doc.issuer,
        }),
      });
      return res.json();
    },
    onSuccess: (data) => {
      toast({
        title: "Document Imported!",
        description: data.message,
        className: "bg-emerald-900/90 border-emerald-500/20 text-white",
      });
      queryClient.invalidateQueries({ queryKey: ['wallet-credentials'] });
      setImporting(null);
    },
    onError: () => {
      toast({
        title: "Import Failed",
        description: "Could not import document.",
        variant: "destructive",
      });
      setImporting(null);
    },
  });

  // Import all documents
  const importAllMutation = useMutation({
    mutationFn: async () => {
      const res = await fetch('/api/digilocker/import-all', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: 1 }),
      });
      return res.json();
    },
    onSuccess: (data) => {
      toast({
        title: "All Documents Imported!",
        description: `Imported ${data.imported.length} of ${data.total} documents.`,
        className: "bg-emerald-900/90 border-emerald-500/20 text-white",
      });
      queryClient.invalidateQueries({ queryKey: ['wallet-credentials'] });
    },
  });

  // Disconnect
  const disconnectMutation = useMutation({
    mutationFn: async () => {
      const res = await fetch('/api/digilocker/disconnect', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: 1 }),
      });
      return res.json();
    },
    onSuccess: () => {
      toast({ title: "Disconnected from DigiLocker" });
      queryClient.invalidateQueries({ queryKey: ['digilocker-status'] });
    },
  });

  const isConnected = statusData?.connected;
  const documents: DigiLockerDocument[] = documentsData?.documents || [];

  return (
    <div className="flex min-h-screen bg-background">
      <Sidebar />

      <main className="flex-1 md:ml-64 p-6 overflow-y-auto">
        <div className="max-w-2xl mx-auto space-y-6">

          {/* Header */}
          <div className="text-center space-y-2">
            <div className="w-20 h-20 mx-auto rounded-2xl bg-gradient-to-br from-blue-600 to-blue-800 flex items-center justify-center shadow-xl shadow-blue-900/30">
              <Shield className="w-10 h-10 text-white" />
            </div>
            <h1 className="text-3xl font-bold">DigiLocker Integration</h1>
            <p className="text-muted-foreground">
              Import your government-issued documents securely to your wallet.
            </p>
            {statusData?.isDemoMode && (
              <Badge variant="outline" className="text-amber-500 border-amber-500/30">
                Demo Mode
              </Badge>
            )}
          </div>

          {/* Status Card */}
          <Card className="border-border">
            <CardHeader>
              <CardTitle className="flex items-center justify-between">
                <span>Connection Status</span>
                {isConnected ? (
                  <Badge className="bg-emerald-500/20 text-emerald-400 border-emerald-500/30">
                    <CheckCircle2 className="w-3 h-3 mr-1" /> Connected
                  </Badge>
                ) : (
                  <Badge variant="secondary">Not Connected</Badge>
                )}
              </CardTitle>
            </CardHeader>
            <CardContent>
              {statusLoading ? (
                <div className="flex items-center justify-center py-8">
                  <Loader2 className="w-6 h-6 animate-spin" />
                </div>
              ) : isConnected ? (
                <div className="space-y-4">
                  <div className="p-4 bg-secondary/30 rounded-lg">
                    <p className="font-medium">{statusData.user?.name || 'User'}</p>
                    <p className="text-sm text-muted-foreground font-mono">
                      ID: {statusData.user?.digilockerid}
                    </p>
                  </div>
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => queryClient.invalidateQueries({ queryKey: ['digilocker-documents'] })}
                    >
                      <RefreshCw className="w-4 h-4 mr-2" /> Refresh
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      className="text-red-500 hover:text-red-400"
                      onClick={() => disconnectMutation.mutate()}
                    >
                      <LogOut className="w-4 h-4 mr-2" /> Disconnect
                    </Button>
                  </div>
                </div>
              ) : (
                <div className="space-y-4">
                  <div className="space-y-3">
                    <div className="flex items-center gap-3 p-3 rounded-lg bg-secondary/30">
                      <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                      <div>
                        <p className="font-medium">Verified Identity</p>
                        <p className="text-sm text-muted-foreground">
                          Access Aadhaar, PAN, and Driving License
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3 p-3 rounded-lg bg-secondary/30">
                      <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                      <div>
                        <p className="font-medium">Blockchain Backed</p>
                        <p className="text-sm text-muted-foreground">
                          Documents are hashed and verified on-chain
                        </p>
                      </div>
                    </div>
                  </div>

                  <Button
                    className="w-full h-12 bg-[#2B6CB0] hover:bg-[#2C5282]"
                    onClick={() => connectMutation.mutate()}
                    disabled={connectMutation.isPending}
                  >
                    {connectMutation.isPending ? (
                      <Loader2 className="w-5 h-5 animate-spin mr-2" />
                    ) : (
                      <Shield className="w-5 h-5 mr-2" />
                    )}
                    Connect with DigiLocker
                  </Button>

                  <p className="text-xs text-center text-muted-foreground">
                    By connecting, you agree to our Terms of Service and Privacy Policy.
                  </p>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Documents List */}
          {isConnected && (
            <Card className="border-border">
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle>Available Documents ({documents.length})</CardTitle>
                  <Button
                    size="sm"
                    onClick={() => importAllMutation.mutate()}
                    disabled={importAllMutation.isPending || documents.length === 0}
                  >
                    {importAllMutation.isPending ? (
                      <Loader2 className="w-4 h-4 animate-spin mr-2" />
                    ) : (
                      <Download className="w-4 h-4 mr-2" />
                    )}
                    Import All
                  </Button>
                </div>
                <CardDescription>
                  Select documents to import into your wallet
                </CardDescription>
              </CardHeader>
              <CardContent>
                {docsLoading ? (
                  <div className="flex items-center justify-center py-8">
                    <Loader2 className="w-6 h-6 animate-spin" />
                  </div>
                ) : documents.length === 0 ? (
                  <p className="text-center text-muted-foreground py-8">
                    No documents found in your DigiLocker account.
                  </p>
                ) : (
                  <div className="space-y-3">
                    {documents.map((doc) => {
                      const Icon = docTypeIcons[doc.doctype] || FileText;
                      const isImporting = importing === doc.uri;

                      return (
                        <motion.div
                          key={doc.uri}
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          className="flex items-center gap-4 p-4 border rounded-lg hover:border-primary/50 transition-colors"
                        >
                          <div className="w-12 h-12 rounded-lg bg-secondary flex items-center justify-center shrink-0">
                            <Icon className="w-6 h-6 text-primary" />
                          </div>
                          <div className="flex-1 min-w-0">
                            <p className="font-medium truncate">{doc.name}</p>
                            <p className="text-sm text-muted-foreground truncate">
                              {doc.issuer} • {doc.date}
                            </p>
                          </div>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => importMutation.mutate(doc)}
                            disabled={isImporting}
                          >
                            {isImporting ? (
                              <Loader2 className="w-4 h-4 animate-spin" />
                            ) : (
                              <>
                                <Download className="w-4 h-4 mr-1" /> Import
                              </>
                            )}
                          </Button>
                        </motion.div>
                      );
                    })}
                  </div>
                )}
              </CardContent>
            </Card>
          )}

          {/* Info Card */}
          <Card className="border-blue-500/20 bg-blue-500/5">
            <CardContent className="pt-6">
              <div className="flex gap-3">
                <AlertCircle className="w-5 h-5 text-blue-400 shrink-0 mt-0.5" />
                <div className="text-sm text-muted-foreground">
                  <p className="font-medium text-foreground mb-1">About DigiLocker</p>
                  <p>
                    DigiLocker is the Government of India's official platform for storing
                    and accessing documents digitally. Documents imported from DigiLocker
                    are legally valid and cryptographically signed.
                  </p>
                  <a
                    href="https://digilocker.gov.in"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-blue-400 hover:underline mt-2"
                  >
                    Learn more <ExternalLink className="w-3 h-3" />
                  </a>
                </div>
              </div>
            </CardContent>
          </Card>

        </div>
      </main>
    </div>
  );
}

/**
 * Platform Connections Page
 * Manages platform connections as defined in PRD Section 5.1 Feature 5
 */

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { motion, AnimatePresence } from "framer-motion";
import { Sidebar } from "@/components/sidebar";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import {
    Link2,
    Shield,
    CheckCircle2,
    XCircle,
    Clock,
    MoreVertical,
    ExternalLink,
    Trash2,
    Settings,
    Bell,
    AlertCircle,
    RefreshCw,
    Loader2
} from "lucide-react";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";

interface PlatformConnection {
    id: string;
    platformName: string;
    platformLogo?: string;
    status: 'active' | 'pending' | 'revoked' | 'expired';
    sharedCredentials: string[];
    permissions: {
        shareIdentity: boolean;
        shareCredentials: boolean;
        shareActivity: boolean;
    };
    connectedAt: string;
    lastAccessedAt: string | null;
    accessCount: number;
}

interface ConnectionRequest {
    id: string;
    platformName: string;
    requestedCredentials: string[];
    requestedPermissions: string[];
    status: string;
    createdAt: string;
    expiresAt: string;
}

export default function PlatformConnections() {
    const queryClient = useQueryClient();
    const [selectedConnection, setSelectedConnection] = useState<PlatformConnection | null>(null);
    const [showDisconnectDialog, setShowDisconnectDialog] = useState(false);
    const [showPermissionsDialog, setShowPermissionsDialog] = useState(false);

    // Fetch connections
    const { data: connectionsData, isLoading } = useQuery({
        queryKey: ['platform-connections'],
        queryFn: async () => {
            const res = await fetch('/api/connections?userId=1');
            return res.json();
        },
    });

    // Fetch pending requests
    const { data: requestsData } = useQuery({
        queryKey: ['connection-requests'],
        queryFn: async () => {
            const res = await fetch('/api/connections/requests?userId=1');
            return res.json();
        },
    });

    // Approve request mutation
    const approveMutation = useMutation({
        mutationFn: async (requestId: string) => {
            const res = await fetch(`/api/connections/requests/${requestId}/approve`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({})
            });
            return res.json();
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['platform-connections'] });
            queryClient.invalidateQueries({ queryKey: ['connection-requests'] });
        }
    });

    // Deny request mutation
    const denyMutation = useMutation({
        mutationFn: async (requestId: string) => {
            const res = await fetch(`/api/connections/requests/${requestId}/deny`, {
                method: 'POST'
            });
            return res.json();
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['connection-requests'] });
        }
    });

    // Disconnect mutation
    const disconnectMutation = useMutation({
        mutationFn: async (connectionId: string) => {
            const res = await fetch(`/api/connections/${connectionId}`, {
                method: 'DELETE'
            });
            return res.json();
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['platform-connections'] });
            setShowDisconnectDialog(false);
            setSelectedConnection(null);
        }
    });

    const connections: PlatformConnection[] = connectionsData?.connections || [];
    const requests: ConnectionRequest[] = requestsData?.requests || [];
    const stats = connectionsData?.stats || { total: 0, active: 0, totalAccessCount: 0 };

    return (
        <div className="flex min-h-screen bg-background">
            <Sidebar />

            <div className="flex-1 md:ml-64 p-6">
                <div className="max-w-2xl mx-auto space-y-6">
                    {/* Header */}
                    <div className="flex items-center justify-between">
                        <div>
                            <h1 className="text-2xl font-bold">Platform Connections</h1>
                            <p className="text-muted-foreground">Manage apps and services connected to your wallet</p>
                        </div>
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => queryClient.invalidateQueries({ queryKey: ['platform-connections'] })}
                        >
                            <RefreshCw className="w-4 h-4 mr-2" />
                            Refresh
                        </Button>
                    </div>

                    {/* Stats */}
                    <div className="grid grid-cols-3 gap-4">
                        <div className="bg-card p-4 rounded-xl border">
                            <div className="text-2xl font-bold text-primary">{stats.active}</div>
                            <div className="text-sm text-muted-foreground">Active</div>
                        </div>
                        <div className="bg-card p-4 rounded-xl border">
                            <div className="text-2xl font-bold">{stats.total}</div>
                            <div className="text-sm text-muted-foreground">Total</div>
                        </div>
                        <div className="bg-card p-4 rounded-xl border">
                            <div className="text-2xl font-bold text-green-600">{stats.totalAccessCount}</div>
                            <div className="text-sm text-muted-foreground">Accesses</div>
                        </div>
                    </div>

                    {/* Pending Requests */}
                    {requests.length > 0 && (
                        <motion.div
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            className="space-y-3"
                        >
                            <div className="flex items-center gap-2">
                                <Bell className="w-4 h-4 text-amber-500" />
                                <h2 className="font-semibold">Pending Requests ({requests.length})</h2>
                            </div>

                            {requests.map((request) => (
                                <div
                                    key={request.id}
                                    className="bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-xl p-4"
                                >
                                    <div className="flex items-start justify-between gap-4">
                                        <div className="flex items-center gap-3">
                                            <div className="w-10 h-10 rounded-full bg-amber-100 dark:bg-amber-800 flex items-center justify-center">
                                                <Link2 className="w-5 h-5 text-amber-600 dark:text-amber-400" />
                                            </div>
                                            <div>
                                                <p className="font-medium">{request.platformName}</p>
                                                <p className="text-xs text-muted-foreground">
                                                    Wants access to: {request.requestedCredentials.join(', ')}
                                                </p>
                                                <p className="text-xs text-amber-600 dark:text-amber-400 mt-1">
                                                    <Clock className="w-3 h-3 inline mr-1" />
                                                    Expires in {Math.round((new Date(request.expiresAt).getTime() - Date.now()) / 3600000)}h
                                                </p>
                                            </div>
                                        </div>

                                        <div className="flex gap-2 shrink-0">
                                            <Button
                                                size="sm"
                                                variant="outline"
                                                onClick={() => denyMutation.mutate(request.id)}
                                                disabled={denyMutation.isPending}
                                            >
                                                <XCircle className="w-4 h-4 mr-1" />
                                                Deny
                                            </Button>
                                            <Button
                                                size="sm"
                                                onClick={() => approveMutation.mutate(request.id)}
                                                disabled={approveMutation.isPending}
                                                className="bg-green-600 hover:bg-green-700"
                                            >
                                                {approveMutation.isPending ? (
                                                    <Loader2 className="w-4 h-4 mr-1 animate-spin" />
                                                ) : (
                                                    <CheckCircle2 className="w-4 h-4 mr-1" />
                                                )}
                                                Approve
                                            </Button>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </motion.div>
                    )}

                    {/* Active Connections */}
                    <div className="space-y-3">
                        <h2 className="font-semibold">Connected Platforms</h2>

                        {isLoading ? (
                            <div className="flex justify-center py-8">
                                <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
                            </div>
                        ) : connections.length === 0 ? (
                            <div className="text-center py-8 text-muted-foreground">
                                <Link2 className="w-12 h-12 mx-auto mb-3 opacity-50" />
                                <p>No connected platforms yet</p>
                                <p className="text-sm">Platforms will appear here once connected</p>
                            </div>
                        ) : (
                            <AnimatePresence>
                                {connections.map((connection, idx) => (
                                    <motion.div
                                        key={connection.id}
                                        initial={{ opacity: 0, x: -20 }}
                                        animate={{ opacity: 1, x: 0 }}
                                        exit={{ opacity: 0, x: 20 }}
                                        transition={{ delay: idx * 0.05 }}
                                        className="bg-card border rounded-xl p-4"
                                    >
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-3">
                                                <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
                                                    <Shield className="w-5 h-5 text-primary" />
                                                </div>
                                                <div>
                                                    <p className="font-medium flex items-center gap-2">
                                                        {connection.platformName}
                                                        <Badge
                                                            variant={connection.status === 'active' ? 'default' : 'secondary'}
                                                            className="text-[10px]"
                                                        >
                                                            {connection.status}
                                                        </Badge>
                                                    </p>
                                                    <p className="text-xs text-muted-foreground">
                                                        {connection.sharedCredentials.length} credentials shared •
                                                        {connection.accessCount} accesses
                                                    </p>
                                                    {connection.lastAccessedAt && (
                                                        <p className="text-xs text-muted-foreground">
                                                            Last access: {new Date(connection.lastAccessedAt).toLocaleDateString()}
                                                        </p>
                                                    )}
                                                </div>
                                            </div>

                                            <DropdownMenu>
                                                <DropdownMenuTrigger asChild>
                                                    <Button variant="ghost" size="icon">
                                                        <MoreVertical className="w-4 h-4" />
                                                    </Button>
                                                </DropdownMenuTrigger>
                                                <DropdownMenuContent align="end">
                                                    <DropdownMenuItem onClick={() => {
                                                        setSelectedConnection(connection);
                                                        setShowPermissionsDialog(true);
                                                    }}>
                                                        <Settings className="w-4 h-4 mr-2" />
                                                        Manage Permissions
                                                    </DropdownMenuItem>
                                                    <DropdownMenuItem>
                                                        <ExternalLink className="w-4 h-4 mr-2" />
                                                        View Activity
                                                    </DropdownMenuItem>
                                                    <DropdownMenuItem
                                                        className="text-red-600"
                                                        onClick={() => {
                                                            setSelectedConnection(connection);
                                                            setShowDisconnectDialog(true);
                                                        }}
                                                    >
                                                        <Trash2 className="w-4 h-4 mr-2" />
                                                        Disconnect
                                                    </DropdownMenuItem>
                                                </DropdownMenuContent>
                                            </DropdownMenu>
                                        </div>
                                    </motion.div>
                                ))}
                            </AnimatePresence>
                        )}
                    </div>
                </div>
            </div>

            {/* Disconnect Confirmation Dialog */}
            <Dialog open={showDisconnectDialog} onOpenChange={setShowDisconnectDialog}>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <AlertCircle className="w-5 h-5 text-red-500" />
                            Disconnect Platform
                        </DialogTitle>
                        <DialogDescription>
                            Are you sure you want to disconnect from {selectedConnection?.platformName}?
                            They will no longer be able to access your credentials.
                        </DialogDescription>
                    </DialogHeader>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setShowDisconnectDialog(false)}>
                            Cancel
                        </Button>
                        <Button
                            variant="destructive"
                            onClick={() => selectedConnection && disconnectMutation.mutate(selectedConnection.id)}
                            disabled={disconnectMutation.isPending}
                        >
                            {disconnectMutation.isPending ? (
                                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                            ) : (
                                <Trash2 className="w-4 h-4 mr-2" />
                            )}
                            Disconnect
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Permissions Dialog */}
            <Dialog open={showPermissionsDialog} onOpenChange={setShowPermissionsDialog}>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>Manage Permissions</DialogTitle>
                        <DialogDescription>
                            Control what {selectedConnection?.platformName} can access
                        </DialogDescription>
                    </DialogHeader>

                    {selectedConnection && (
                        <div className="space-y-4 py-4">
                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="font-medium">Share Identity</p>
                                    <p className="text-sm text-muted-foreground">Allow access to your verified identity</p>
                                </div>
                                <Switch defaultChecked={selectedConnection.permissions.shareIdentity} />
                            </div>

                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="font-medium">Share Credentials</p>
                                    <p className="text-sm text-muted-foreground">Allow access to selected credentials</p>
                                </div>
                                <Switch defaultChecked={selectedConnection.permissions.shareCredentials} />
                            </div>

                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="font-medium">Share Activity</p>
                                    <p className="text-sm text-muted-foreground">Allow access to your activity history</p>
                                </div>
                                <Switch defaultChecked={selectedConnection.permissions.shareActivity} />
                            </div>
                        </div>
                    )}

                    <DialogFooter>
                        <Button variant="outline" onClick={() => setShowPermissionsDialog(false)}>
                            Cancel
                        </Button>
                        <Button onClick={() => setShowPermissionsDialog(false)}>
                            Save Changes
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

import { useState } from "react";
import { useLocation, useRoute } from "wouter";
import { Sidebar } from "@/components/sidebar";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import {
  QrCode,
  Download,
  Link as LinkIcon,
  EyeOff,
  ShieldCheck,
  Building2,
  CheckCircle2,
  ArrowLeft,
  Share2,
  FileText,
  Clock,
  Eye,
  Loader2,
  Copy,
  ExternalLink,
  AlertTriangle
} from "lucide-react";
import { motion } from "framer-motion";
import { ShareModal } from "@/components/share-modal";
import { useQuery } from "@tanstack/react-query";

interface CredentialData {
  id: string;
  type: string[];
  issuer: string;
  issuanceDate: string;
  expirationDate?: string;
  data: any;
  category: string;
  anchorStatus: string;
  anchorTxHash?: string;
  blockNumber?: number;
  hash: string;
  verificationCount: number;
}

interface ShareRecord {
  id: string;
  shareType: string;
  disclosedFields: string[];
  expiry: string;
  createdAt: string;
  accessLog: { timestamp: string; ip: string }[];
  revoked: boolean;
}

interface ConsentLog {
  id: string;
  action: string;
  disclosedFields: string[];
  recipientName?: string;
  purpose: string;
  timestamp: string;
}

export default function CredentialDetail() {
  const [location, setLocation] = useLocation();
  const [match, params] = useRoute("/credential/:id");
  const [shareModalOpen, setShareModalOpen] = useState(false);
  const [copied, setCopied] = useState(false);

  // Fetch credential details
  const { data, isLoading, error } = useQuery({
    queryKey: [`wallet-credential-${params?.id}`],
    queryFn: async () => {
      const res = await fetch(`/api/wallet/credentials/${params?.id}?userId=1`);
      if (!res.ok) throw new Error('Failed to fetch credential');
      return res.json();
    },
    enabled: !!params?.id,
  });

  const credential: CredentialData | undefined = data?.credential;
  const shares: ShareRecord[] = data?.shares || [];
  const consentLogs: ConsentLog[] = data?.consentLogs || [];

  const handleCopyHash = () => {
    if (credential?.hash) {
      navigator.clipboard.writeText(credential.hash);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  if (isLoading) {
    return (
      <div className="flex min-h-screen bg-background">
        <Sidebar />
        <div className="flex-1 md:ml-64 flex items-center justify-center">
          <Loader2 className="w-8 h-8 animate-spin text-primary" />
        </div>
      </div>
    );
  }

  if (error || !credential) {
    return (
      <div className="flex min-h-screen bg-background">
        <Sidebar />
        <div className="flex-1 md:ml-64 flex flex-col items-center justify-center gap-4">
          <AlertTriangle className="w-12 h-12 text-amber-500" />
          <p className="text-muted-foreground">Credential not found</p>
          <Button onClick={() => setLocation("/")}>Go Back</Button>
        </div>
      </div>
    );
  }

  const getCategoryColor = (category: string) => {
    const colors: Record<string, string> = {
      academic: "from-blue-600 to-blue-800",
      employment: "from-purple-600 to-purple-800",
      skill: "from-green-600 to-green-800",
      government: "from-red-600 to-red-800",
    };
    return colors[category] || "from-gray-600 to-gray-800";
  };

  const actions = [
    {
      icon: QrCode,
      label: "Generate QR",
      desc: "For in-person verification",
      onClick: () => setShareModalOpen(true)
    },
    {
      icon: Download,
      label: "Download PDF",
      desc: "Signed official copy",
      onClick: () => alert("PDF download coming soon")
    },
    {
      icon: LinkIcon,
      label: "Share Link",
      desc: "Time-limited URL",
      onClick: () => setShareModalOpen(true)
    },
    {
      icon: EyeOff,
      label: "Selective Disclosure",
      desc: "Hide sensitive fields",
      onClick: () => setShareModalOpen(true)
    }
  ];

  return (
    <div className="flex min-h-screen bg-background">
      <Sidebar />

      <div className="flex-1 md:ml-64 flex flex-col h-screen overflow-y-auto bg-secondary/30">
        {/* Header */}
        <div className="sticky top-0 z-10 bg-card/80 backdrop-blur-md border-b border-border px-6 py-4 flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => setLocation("/")}>
            <ArrowLeft className="w-5 h-5" />
          </Button>
