  Shield,
  Cloud,
  Globe,
  Moon,
  LogOut,
  Download,
  Upload,
  Key,
  Fingerprint,
  AlertTriangle,
  CheckCircle2,
  Copy,
  Loader2,
  History,
  Bell,
  Lock,
  Activity as ActivityIcon,
  Calendar
} from "lucide-react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
