const LEGACY_API_SUNSET_HEADER =
  process.env.API_LEGACY_SUNSET ?? new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toUTCString();

function withLegacyDeprecation(routeHandler: Router, successorPath: string): Router {
  const alias = Router();
  alias.use((_req, res, next) => {
    res.setHeader("Deprecation", "true");
    res.setHeader("Sunset", LEGACY_API_SUNSET_HEADER);
    res.setHeader("Link", `<${successorPath}>; rel="successor-version"`);
    next();
  });
  alias.use(routeHandler);
  return alias;
}

export async function registerRoutes(
  httpServer: Server,
  app: Express
): Promise<Server> {
  const allowDemoRoutes =
    process.env.NODE_ENV !== "production" && process.env.ALLOW_DEMO_ROUTES === "true";

  // Health check endpoint for Railway
  app.get("/api/health", (_req, res) => {
    res.status(200).json({ status: "ok", timestamp: new Date().toISOString() });
  });

  // Canonical V1 routes
  app.use("/api/v1", authRoutes);
  app.use("/api/v1", walletRoutes);
  app.use("/api/v1", credentialsRoutes);
  app.use("/api/v1", sharingRoutes);
  app.use("/api/v1", notificationsRoutes);
  app.use("/api/v1", userRoutes);
  app.use("/api/v1", digilockerRoutes);
  app.use("/api/v1/trust-score", trustScoreRoutes);
  app.use("/api/v1/reputation", reputationRoutes);
  app.use("/api/v1", complianceRoutes);
  app.use("/api/v1/connections", connectionsRoutes);
  app.use("/api/v1/identity", identityRoutes);

  // Deprecated legacy aliases (/api/*)
  app.use("/api", withLegacyDeprecation(authRoutes, "/api/v1/auth"));
  app.use("/api", withLegacyDeprecation(walletRoutes, "/api/v1/wallet"));
  app.use("/api", withLegacyDeprecation(credentialsRoutes, "/api/v1/wallet/credentials"));
  app.use("/api", withLegacyDeprecation(sharingRoutes, "/api/v1/wallet/share"));
  app.use("/api", withLegacyDeprecation(notificationsRoutes, "/api/v1/inbox"));
  app.use("/api", withLegacyDeprecation(userRoutes, "/api/v1/user"));
  app.use("/api", withLegacyDeprecation(digilockerRoutes, "/api/v1/digilocker"));
  app.use("/api/trust-score", withLegacyDeprecation(trustScoreRoutes, "/api/v1/trust-score"));
  app.use("/api/reputation", withLegacyDeprecation(reputationRoutes, "/api/v1/reputation"));
  app.use("/api", withLegacyDeprecation(complianceRoutes, "/api/v1/compliance"));
  app.use("/api/connections", withLegacyDeprecation(connectionsRoutes, "/api/v1/connections"));
  if (allowDemoRoutes) {
    app.use("/api/v1/claims", claimsRoutes);      // Claims Verification API (B2B demo path)
  } else {
    app.use("/api/v1/claims", (_req, res) => {
      res.status(503).json({
        error: "Claims verification demo module is disabled.",
        hint: "Enable ALLOW_DEMO_ROUTES=true in non-production to access demo claims routes.",
      });
    });
  }
  app.use("/api/identity", withLegacyDeprecation(identityRoutes, "/api/v1/identity"));

  return httpServer;
}

import { Router } from 'express';
import { storage } from '../storage';
import {
    hashPassword,
    comparePassword,
    generateAccessToken,
    generateRefreshToken,
    refreshAccessToken,
    invalidateRefreshToken,
    invalidateAccessToken,
    verifyAccessToken,
    authMiddleware,
    checkRateLimit,
    validatePasswordStrength,
    AuthUser,
} from '../services/auth-service';

const router = Router();
const allowLegacyLoginBypass =
    process.env.NODE_ENV !== 'production' && process.env.ALLOW_DEMO_ROUTES === 'true';

/**
 * Register a new user
 */
router.post('/auth/register', async (req, res) => {
    try {
        const { username, email, password, name } = req.body;

        if (!username || !password) {
            return res.status(400).json({ error: 'Username and password required' });
        }

        const passwordValidation = validatePasswordStrength(password);
        if (!passwordValidation.isValid) {
            return res.status(400).json({
                error: 'Password does not meet security requirements',
                details: passwordValidation.errors,
            });
        }

        // Rate limit registration
        if (!checkRateLimit(`register:${req.ip}`, 5, 60 * 60 * 1000)) {
            return res.status(429).json({ error: 'Too many registration attempts' });
        }

        // Check if user exists
        const existing = await storage.getUserByUsername(username);
        if (existing) {
            return res.status(409).json({ error: 'Username already exists' });
        }

        // Hash password and create user
        const passwordHash = await hashPassword(password);
        const user = await storage.createUser({
            username,
            name: name || username,
            email,
            password: passwordHash,
        });

        // Generate tokens
        const authUser: AuthUser = {
            id: user.id,
            username: user.username,
            email: user.email || undefined,
            role: 'holder',
        };

        const accessToken = generateAccessToken(authUser);
        const refreshToken = generateRefreshToken(authUser);

        res.status(201).json({
            success: true,
            user: {
                id: user.id,
                username: user.username,
                name: user.name,
                email: user.email,
            },
            tokens: {
                accessToken,
                refreshToken,
                expiresIn: 900, // 15 minutes
            },
        });
    } catch (error: any) {
        console.error('[Auth] Register error:', error);
        res.status(500).json({ error: 'Registration failed' });
    }
});

/**
 * Login with username/password
 */
router.post('/auth/login', async (req, res) => {
    try {
        const { username, password } = req.body;

        if (!username || !password) {
            return res.status(400).json({ error: 'Username and password required' });
        }

        // Rate limit login attempts
        if (!checkRateLimit(`login:${username}`, 10, 15 * 60 * 1000)) {
            return res.status(429).json({ error: 'Too many login attempts. Try again later.' });
        }

        // Find user
        const user = await storage.getUserByUsername(username);
        if (!user) {
            return res.status(401).json({ error: 'Invalid credentials' });
        }

        // Verify password
        const passwordHash = (user as any).password;
        if (!passwordHash) {
            if (!allowLegacyLoginBypass) {
                return res.status(401).json({ error: 'Invalid credentials' });
            }
            console.warn('[Auth] Allowing legacy no-password login because ALLOW_DEMO_ROUTES=true');
        } else {
            const valid = await comparePassword(password, passwordHash);
            if (!valid) {
                return res.status(401).json({ error: 'Invalid credentials' });
            }
        }

        // Generate tokens
        const authUser: AuthUser = {
            id: user.id,
            username: user.username,
            email: user.email || undefined,
            role: 'holder',
        };

        const accessToken = generateAccessToken(authUser);
        const refreshToken = generateRefreshToken(authUser);

        res.json({
            success: true,
            user: {
                id: user.id,
                username: user.username,
                name: user.name,
                email: user.email,
                did: user.did,
            },
            tokens: {
                accessToken,
                refreshToken,
                expiresIn: 900,
            },
        });
    } catch (error: any) {
        console.error('[Auth] Login error:', error);
        res.status(500).json({ error: 'Login failed' });
    }
});

/**
 * Refresh access token
 */
router.post('/auth/refresh', (req, res) => {
    try {
        const { refreshToken } = req.body;

        if (!refreshToken) {
            return res.status(400).json({ error: 'Refresh token required' });
        }

        const tokens = refreshAccessToken(refreshToken);
        if (!tokens) {
            return res.status(401).json({ error: 'Invalid refresh token' });
        }

        res.json({
            success: true,
            tokens: {
                accessToken: tokens.accessToken,
                refreshToken: tokens.refreshToken,
                expiresIn: 900,
            },
        });
    } catch (error) {
        res.status(500).json({ error: 'Token refresh failed' });
    }
});

/**
 * Logout - invalidate tokens
 */
router.post('/auth/logout', authMiddleware, (req, res) => {
    try {
        const { refreshToken } = req.body;
        const authHeader = req.headers.authorization;

        if (refreshToken) {
            invalidateRefreshToken(refreshToken);
        }

        if (authHeader) {
            const accessToken = authHeader.substring(7);
            invalidateAccessToken(accessToken);
        }

        res.json({ success: true });
    } catch (error) {
        res.status(500).json({ error: 'Logout failed' });
    }
});

/**
 * Get current user profile
 */
router.get('/auth/me', authMiddleware, async (req, res) => {
    try {
        const user = await storage.getUser(Number(req.user!.userId));
        if (!user) {
            return res.status(404).json({ error: 'User not found' });
        }

        res.json({
            id: user.id,
            username: user.username,
            name: user.name,
            email: user.email,
            did: user.did,
            avatarUrl: user.avatarUrl,
            bio: user.bio,
        });
    } catch (error) {
        res.status(500).json({ error: 'Failed to get profile' });
    }
});

/**
 * Update user profile
 */
router.patch('/auth/me', authMiddleware, async (req, res) => {
    try {
        const { name, email, bio, avatarUrl } = req.body;

        const updated = await storage.updateUser(Number(req.user!.userId), {
            name,
            email,
            bio,
            avatarUrl,
        });

        res.json({
            success: true,
            user: {
                id: updated.id,
                username: updated.username,
                name: updated.name,
                email: updated.email,
                bio: updated.bio,
                avatarUrl: updated.avatarUrl,
            },
        });
    } catch (error) {
        res.status(500).json({ error: 'Failed to update profile' });
    }
});

/**
 * Change password
 */
router.post('/auth/change-password', authMiddleware, async (req, res) => {
    try {
        const { currentPassword, newPassword } = req.body;

        if (!newPassword) {
            return res.status(400).json({ error: 'newPassword is required' });
        }

        const passwordValidation = validatePasswordStrength(newPassword);
        if (!passwordValidation.isValid) {
            return res.status(400).json({
                error: 'Password does not meet security requirements',
                details: passwordValidation.errors,
            });
        }

        const user = await storage.getUser(Number(req.user!.userId));
        if (!user) {
            return res.status(404).json({ error: 'User not found' });
        }

        // Verify current password if exists
        const passwordHash = (user as any).password;
        if (passwordHash && currentPassword) {
            const valid = await comparePassword(currentPassword, passwordHash);
            if (!valid) {
                return res.status(401).json({ error: 'Current password is incorrect' });
            }
        }

        // Update password
        const newHash = await hashPassword(newPassword);
        await storage.updateUser(Number(req.user!.userId), { password: newHash } as any);

        res.json({ success: true, message: 'Password updated' });
    } catch (error) {
        res.status(500).json({ error: 'Failed to change password' });
    }
});

/**
 * Verify token - Cross-app token validation endpoint
 * Used by other CredVerse apps to validate tokens from this app
 */
router.post('/auth/verify-token', (req, res) => {
    try {
        const { token } = req.body;

        if (!token) {
            return res.status(400).json({ valid: false, error: 'Token required' });
        }

        const payload = verifyAccessToken(token);

        if (!payload) {
            return res.status(401).json({ valid: false, error: 'Invalid or expired token' });
        }

        res.json({
            valid: true,
            user: {
                userId: payload.userId,
                username: payload.username,
                role: payload.role,
            },
            app: 'wallet',
        });
    } catch (error) {
        res.status(500).json({ valid: false, error: 'Token verification failed' });
    }
});

export default router;

/**
 * Claims API Routes
 * Implements PRD v3.1 Feature 2: Claims Verification System
 * 
 * Endpoints:
 * - POST /api/v1/claims/verify - Submit claim for verification
 * - GET /api/v1/claims/:id - Get claim status
 * - POST /api/v1/evidence/upload - Upload evidence file
 * - GET /api/v1/evidence/:id/analysis - Get evidence analysis
 */

import { Router, Request, Response } from 'express';
import { verifyClaim, ClaimVerifyRequest, getClaimById } from '../services/claims-service';
import { analyzeEvidence, EvidenceUploadRequest } from '../services/evidence-analysis';

const router = Router();

// In-memory store for claims (would be database in production)
const claimsStore = new Map<string, any>();
const evidenceStore = new Map<string, any>();

/**
 * POST /api/v1/claims/verify
 * Submit a claim for verification
 * 
 * Per PRD v3.1: Process claim through 3-layer verification and return Trust Score
 */
router.post('/verify', async (req: Request, res: Response) => {
    try {
        const request: ClaimVerifyRequest = {
            userId: req.body.user_id || req.body.userId,
            claimType: req.body.claim_type || req.body.claimType || 'identity_check',
            claimAmount: req.body.claim_amount || req.body.claimAmount,
            description: req.body.description || '',
            timeline: req.body.timeline || [],
            evidence: req.body.evidence || [],
            userCredentials: req.body.user_credentials || req.body.userCredentials || []
        };

        // Validate required fields
        if (!request.userId) {
            return res.status(400).json({
                success: false,
                error: 'user_id is required'
            });
        }

        // Process the claim through 3-layer verification
        const result = await verifyClaim(request);

        // Store the claim result
        claimsStore.set(result.claimId, {
            ...result,
            request,
            createdAt: new Date().toISOString()
        });

        // Return PRD v3.1 format response
        res.json({
            success: true,
            claim_id: result.claimId,
            trust_score: result.trustScore,
            recommendation: result.recommendation,
            breakdown: {
                identity_score: result.breakdown.identityScore,
                integrity_score: result.breakdown.integrityScore,
                authenticity_score: result.breakdown.authenticityScore
            },
            red_flags: result.redFlags,
            ai_analysis: {
                deepfake_detected: result.aiAnalysis.deepfakeDetected,
                timeline_consistent: result.aiAnalysis.timelineConsistent,
                fraud_pattern_match: result.aiAnalysis.fraudPatternMatch,
                llm_confidence: result.aiAnalysis.llmConfidence
            },
            processing_time_seconds: result.processingTimeMs / 1000,
            cost_breakdown: {
                identity_verification: result.costBreakdown.identityVerification,
                ml_inference: result.costBreakdown.mlInference,
                llm_analysis: result.costBreakdown.llmAnalysis,
                deepfake_check: result.costBreakdown.deepfakeCheck,
                blockchain_timestamp: result.costBreakdown.blockchainTimestamp,
                total_inr: result.costBreakdown.totalInr
            }
        });
    } catch (error: any) {
        console.error('Claims verification error:', error);
        res.status(500).json({
            success: false,
            error: 'Failed to verify claim',
            message: error.message
        });
    }
});

/**
 * GET /api/v1/claims/:id
 * Get claim verification status
 */
router.get('/:id', async (req: Request, res: Response) => {
    try {
