/**
 * POST /api/connections/requests/:id/approve
 * Approve a connection request
 */
router.post('/requests/:id/approve', async (req: Request, res: Response) => {
    try {
        const { id } = req.params;
        const { permissions } = req.body;

        const request = pendingRequests.get(id);
        if (!request) {
            return res.status(404).json({
                success: false,
                error: 'Request not found'
            });
        }

        // Create connection from request
        const connection: PlatformConnection = {
            id: `conn-${Date.now()}`,
            userId: request.userId,
            platformId: request.platformId,
            platformName: request.platformName,
            status: 'active',
            sharedCredentials: request.requestedCredentials,
            permissions: permissions || {
                shareIdentity: true,
                shareCredentials: true,
                shareActivity: false
            },
            connectedAt: new Date(),
            lastAccessedAt: null,
            expiresAt: null,
            accessCount: 0
        };

        connections.set(connection.id, connection);
        request.status = 'approved';
        pendingRequests.set(id, request);

        res.json({
            success: true,
            connection,
            message: `Connected to ${request.platformName}`
        });
    } catch (error: any) {
        console.error('Approve request error:', error);
        res.status(500).json({
            success: false,
            error: 'Failed to approve request'
        });
    }
});

/**
 * POST /api/connections/requests/:id/deny
 * Deny a connection request
 */
router.post('/requests/:id/deny', async (req: Request, res: Response) => {
    try {
        const { id } = req.params;

        const request = pendingRequests.get(id);
        if (!request) {
            return res.status(404).json({
                success: false,
                error: 'Request not found'
            });
        }

        request.status = 'denied';
        pendingRequests.set(id, request);

        res.json({
            success: true,
            message: `Denied request from ${request.platformName}`
        });
    } catch (error: any) {
        console.error('Deny request error:', error);
        res.status(500).json({
            success: false,
            error: 'Failed to deny request'
        });
    }
});

/**
 * PUT /api/connections/:id/permissions
 * Update permissions for a connection
 */
router.put('/:id/permissions', async (req: Request, res: Response) => {
    try {
        const { id } = req.params;
        const { permissions } = req.body;

        const connection = connections.get(id);
        if (!connection) {
            return res.status(404).json({
                success: false,
                error: 'Connection not found'
            });
        }

        connection.permissions = {
            ...connection.permissions,
            ...permissions
        };
        connections.set(id, connection);

        res.json({
            success: true,
            connection,
            message: 'Permissions updated'
        });
    } catch (error: any) {
        console.error('Update permissions error:', error);
        res.status(500).json({
            success: false,
            error: 'Failed to update permissions'
        });
    }
});

/**
 * DELETE /api/connections/:id
 * Disconnect/revoke a platform connection
 */
router.delete('/:id', async (req: Request, res: Response) => {
    try {
        const { id } = req.params;

        const connection = connections.get(id);
        if (!connection) {
            return res.status(404).json({
                success: false,
                error: 'Connection not found'
            });
        }

        connection.status = 'revoked';
        connections.set(id, connection);

        res.json({
            success: true,
            message: `Disconnected from ${connection.platformName}`
        });
    } catch (error: any) {
        console.error('Disconnect error:', error);
        res.status(500).json({
            success: false,
            error: 'Failed to disconnect'
        });
    }
});

/**
