            issuerName,
            recipientDid,
            credential,
            { recipientEmail, expiryHours }
        );

        res.json({
            success: true,
            offerId: result.offerId,
            status: result.status,
            message: 'Credential offer sent to wallet',
        });
    } catch (error: any) {
        res.status(500).json({ error: error.message });
    }
});

