/**
 * Generate credentials from verified identity data
 */
export function generateCredentialsFromIdentity(identityData: {
    livenessVerified: boolean;
    documentVerified: boolean;
    digilockerConnected: boolean;
    dob?: string;
    country?: string;
    state?: string;
    emailVerified?: boolean;
    phoneVerified?: boolean;
}): UserCredential[] {
    const credentials: UserCredential[] = [];
    const now = new Date();
    const oneYear = new Date(now.getTime() + 365 * 24 * 60 * 60 * 1000);

    // Verified Human - requires liveness
    if (identityData.livenessVerified) {
        credentials.push({
            id: `cred_${Date.now()}_vh`,
            userId: '',
            type: 'verified_human',
            status: 'active',
            issuedAt: now,
            expiresAt: oneYear,
            usageCount: 0,
            lastUsedAt: null,
            data: { verifiedAt: now.toISOString() }
        });
    }

    // Age credentials - requires DOB from document
    if (identityData.documentVerified && identityData.dob) {
        const age = calculateAge(identityData.dob);

        if (age >= 18) {
            credentials.push({
                id: `cred_${Date.now()}_a18`,
                userId: '',
                type: 'age_18',
                status: 'active',
                issuedAt: now,
                expiresAt: oneYear,
                usageCount: 0,
                lastUsedAt: null,
                data: { verifiedAge: '18+' } // Zero-knowledge: doesn't reveal actual age
            });
        }

        if (age >= 21) {
            credentials.push({
                id: `cred_${Date.now()}_a21`,
                userId: '',
                type: 'age_21',
                status: 'active',
                issuedAt: now,
                expiresAt: oneYear,
                usageCount: 0,
                lastUsedAt: null,
                data: { verifiedAge: '21+' }
            });
        }
    }

    // Location credential
    if (identityData.documentVerified && identityData.country) {
        credentials.push({
            id: `cred_${Date.now()}_loc`,
            userId: '',
            type: 'location',
            status: 'active',
            issuedAt: now,
            expiresAt: oneYear,
            usageCount: 0,
            lastUsedAt: null,
            data: {
                country: identityData.country,
                state: identityData.state || null
            }
        });
    }

    // Government ID credential
    if (identityData.documentVerified || identityData.digilockerConnected) {
        credentials.push({
            id: `cred_${Date.now()}_gid`,
            userId: '',
            type: 'government_id',
            status: 'active',
            issuedAt: now,
            expiresAt: null, // Doesn't expire
            usageCount: 0,
            lastUsedAt: null,
            data: {
                verified: true,
                source: identityData.digilockerConnected ? 'digilocker' : 'document_scan'
            }
        });
    }

    // Email verified
    if (identityData.emailVerified) {
        credentials.push({
            id: `cred_${Date.now()}_email`,
            userId: '',
            type: 'email_verified',
            status: 'active',
            issuedAt: now,
            expiresAt: null,
            usageCount: 0,
            lastUsedAt: null,
            data: { verified: true }
        });
    }

    // Phone verified
    if (identityData.phoneVerified) {
        credentials.push({
            id: `cred_${Date.now()}_phone`,
            userId: '',
            type: 'phone_verified',
            status: 'active',
            issuedAt: now,
            expiresAt: null,
            usageCount: 0,
            lastUsedAt: null,
            data: { verified: true }
        });
    }

    return credentials;
}

/**
 * Calculate age from date of birth
 */
function calculateAge(dob: string): number {
    const birthDate = new Date(dob);
    const today = new Date();
    let age = today.getFullYear() - birthDate.getFullYear();
    const monthDiff = today.getMonth() - birthDate.getMonth();

    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {
        age--;
    }

    return age;
}

/**
 * Get credential type info
 */
export function getCredentialTypeInfo(type: string): CredentialType | undefined {
    return CREDENTIAL_TYPES.find(ct => ct.type === type);
}

/**
 * Check if user has required credentials
 */
export function hasRequiredCredentials(
    userCredentials: string[],
    required: string[]
): { hasAll: boolean; missing: string[] } {
    const missing = required.filter(r => !userCredentials.includes(r));
    return {
        hasAll: missing.length === 0,
        missing
    };
}

/**
 * Format credential for display
 */
export function formatCredentialForDisplay(credential: UserCredential): {
    name: string;
    icon: string;
    status: string;
    usageText: string;
} {
    const typeInfo = getCredentialTypeInfo(credential.type);

    return {
        name: typeInfo?.name || credential.type,
        icon: typeInfo?.icon || '📄',
        status: credential.status === 'active'
            ? (credential.expiresAt && new Date(credential.expiresAt) < new Date() ? 'expired' : 'active')
            : credential.status,
        usageText: credential.usageCount > 0
            ? `Used ${credential.usageCount} time${credential.usageCount > 1 ? 's' : ''}`
            : 'Never used'
    };
}

import crypto from 'crypto';

/**
 * Crypto utilities for CredVerse Wallet
 * Provides encryption, signing, and key management
 */

// AES-256-GCM encryption
const ALGORITHM = 'aes-256-gcm';
const KEY_LENGTH = 32; // 256 bits
const IV_LENGTH = 16;
const AUTH_TAG_LENGTH = 16;

export interface EncryptedData {
    ciphertext: string;
    iv: string;
    authTag: string;
}

export interface KeyPair {
    publicKey: string;
    privateKey: string;
    algorithm: 'Ed25519' | 'secp256k1';
}

/**
 * Generate a random encryption key
 */
export function generateEncryptionKey(): string {
    return crypto.randomBytes(KEY_LENGTH).toString('hex');
}

/**
 * Encrypt data using AES-256-GCM
 */
export function encrypt(plaintext: string, keyHex: string): EncryptedData {
    const key = Buffer.from(keyHex, 'hex');
    const iv = crypto.randomBytes(IV_LENGTH);

    const cipher = crypto.createCipheriv(ALGORITHM, key, iv);
    let ciphertext = cipher.update(plaintext, 'utf8', 'hex');
    ciphertext += cipher.final('hex');

    const authTag = cipher.getAuthTag();

    return {
        ciphertext,
        iv: iv.toString('hex'),
        authTag: authTag.toString('hex'),
    };
}

/**
 * Decrypt data using AES-256-GCM
 */
export function decrypt(encrypted: EncryptedData, keyHex: string): string {
    const key = Buffer.from(keyHex, 'hex');
    const iv = Buffer.from(encrypted.iv, 'hex');
    const authTag = Buffer.from(encrypted.authTag, 'hex');

    const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);
    decipher.setAuthTag(authTag);

    let plaintext = decipher.update(encrypted.ciphertext, 'hex', 'utf8');
    plaintext += decipher.final('utf8');

    return plaintext;
}

/**
 * Generate Ed25519 keypair for DIDs
 */
export function generateEd25519KeyPair(): KeyPair {
    const { publicKey, privateKey } = crypto.generateKeyPairSync('ed25519');

    return {
        publicKey: publicKey.export({ type: 'spki', format: 'der' }).toString('base64url'),
        privateKey: privateKey.export({ type: 'pkcs8', format: 'der' }).toString('base64url'),
        algorithm: 'Ed25519',
    };
}

/**
 * Sign data using Ed25519 private key
 */
export function sign(data: string, privateKeyBase64: string): string {
    const privateKeyDer = Buffer.from(privateKeyBase64, 'base64url');
    const privateKey = crypto.createPrivateKey({
        key: privateKeyDer,
        format: 'der',
        type: 'pkcs8',
    });

    const signature = crypto.sign(null, Buffer.from(data), privateKey);
    return signature.toString('base64url');
}

/**
 * Verify signature using Ed25519 public key
 */
export function verify(data: string, signature: string, publicKeyBase64: string): boolean {
    try {
        const publicKeyDer = Buffer.from(publicKeyBase64, 'base64url');
        const publicKey = crypto.createPublicKey({
            key: publicKeyDer,
            format: 'der',
            type: 'spki',
        });

        return crypto.verify(null, Buffer.from(data), publicKey, Buffer.from(signature, 'base64url'));
    } catch {
        return false;
    }
}

/**
 * Hash data using SHA-256
 */
export function sha256(data: string): string {
    return crypto.createHash('sha256').update(data).digest('hex');
}

/**
 * Generate a multibase-encoded public key (for did:key)
 */
export function toMultibase(publicKey: string): string {
    // Ed25519 multicodec prefix: 0xed01
    const multicodecPrefix = Buffer.from([0xed, 0x01]);
    const publicKeyBytes = Buffer.from(publicKey, 'base64url');
    const multicodec = Buffer.concat([multicodecPrefix, publicKeyBytes]);

    // Base58btc encoding with 'z' prefix
    return 'z' + base58Encode(multicodec);
}

/**
 * Simple Base58 encoding (Bitcoin alphabet)
 */
function base58Encode(buffer: Buffer): string {
    const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

    let num = BigInt('0x' + buffer.toString('hex'));
    let result = '';

    while (num > 0) {
        const remainder = Number(num % BigInt(58));
        num = num / BigInt(58);
        result = ALPHABET[remainder] + result;
    }

    // Handle leading zeros
    for (let i = 0; i < buffer.length && buffer[i] === 0; i++) {
        result = '1' + result;
    }

    return result;
}

/**
 * Generate a random nonce
 */
export function generateNonce(): string {
    return crypto.randomBytes(16).toString('hex');
}

/**
 * Generate a time-limited access token
 */
export function generateAccessToken(payload: object, expiryMinutes: number): { token: string; expiry: Date } {
    const expiry = new Date(Date.now() + expiryMinutes * 60 * 1000);
    const tokenData = {
        ...payload,
        exp: expiry.getTime(),
        nonce: generateNonce(),
    };

    const token = Buffer.from(JSON.stringify(tokenData)).toString('base64url');
    return { token, expiry };
}

/**
 * Validate access token
 */
export function validateAccessToken(token: string): { valid: boolean; payload?: any; expired?: boolean } {
    try {
        const payload = JSON.parse(Buffer.from(token, 'base64url').toString());

        if (payload.exp && Date.now() > payload.exp) {
            return { valid: false, expired: true };
        }

        return { valid: true, payload };
    } catch {
        return { valid: false };
    }
}

export interface DeepfakeDetectionResult {
    verdict: 'real' | 'fake' | 'unknown';
    confidence: number | null;
    provider: string;
    reason?: string;
}

export async function detectDeepfakeFromUrl(url: string): Promise<DeepfakeDetectionResult> {
    const endpoint = process.env.DEEPFAKE_API_URL;
    const apiKey = process.env.DEEPFAKE_API_KEY;

    if (!endpoint || !apiKey) {
        return {
            verdict: 'unknown',
            confidence: null,
            provider: 'not_configured',
            reason: 'DEEPFAKE_API_URL or DEEPFAKE_API_KEY not configured',
        };
    }

    try {
        const response = await fetch(endpoint, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                Authorization: `Bearer ${apiKey}`,
            },
            body: JSON.stringify({ url }),
        });

        if (!response.ok) {
            return {
                verdict: 'unknown',
                confidence: null,
                provider: 'remote_api',
                reason: `Provider returned status ${response.status}`,
            };
        }

        const data = await response.json();
        const score = typeof data.score === 'number' ? data.score : null;
        const isFake = data.isFake === true || (typeof score === 'number' && score >= 0.7);
        return {
            verdict: isFake ? 'fake' : 'real',
            confidence: score,
            provider: data.provider || 'remote_api',
        };
    } catch (error: any) {
        return {
            verdict: 'unknown',
            confidence: null,
            provider: 'remote_api',
            reason: error?.message || 'Deepfake provider request failed',
        };
    }
}

import { generateEd25519KeyPair, toMultibase, sign, verify, encrypt, decrypt, generateEncryptionKey, sha256 } from './crypto-utils';

/**
 * DID Service for CredVerse Wallet
 * Implements did:key method for decentralized identifiers
 */

export interface DIDDocument {
    '@context': string[];
    id: string;
    verificationMethod: VerificationMethod[];
    authentication: string[];
    assertionMethod: string[];
    keyAgreement?: string[];
}

export interface VerificationMethod {
    id: string;
    type: string;
    controller: string;
    publicKeyMultibase: string;
}

export interface DIDKeyPair {
    did: string;
    publicKey: string;
    encryptedPrivateKey: {
        ciphertext: string;
        iv: string;
        authTag: string;
    };
    algorithm: string;
    createdAt: Date;
}

export interface DIDResolutionResult {
    didDocument: DIDDocument | null;
    didResolutionMetadata: {
        error?: string;
        contentType?: string;
    };
    didDocumentMetadata: {
        created?: string;
        updated?: string;
    };
}

/**
 * DID Service - handles DID creation, resolution, and key management
 */
export class DIDService {
    private encryptionKey: string;

    constructor() {
        // In production, this would come from secure environment or HSM
        this.encryptionKey = process.env.DID_ENCRYPTION_KEY || generateEncryptionKey();
    }

    /**
     * Create a new DID with keypair
     */
    async createDID(): Promise<DIDKeyPair> {
        const keyPair = generateEd25519KeyPair();

        // Create did:key identifier from public key
        const multibaseKey = toMultibase(keyPair.publicKey);
        const did = `did:key:${multibaseKey}`;

        // Encrypt private key for storage
        const encryptedPrivateKey = encrypt(keyPair.privateKey, this.encryptionKey);

        return {
            did,
            publicKey: keyPair.publicKey,
            encryptedPrivateKey,
            algorithm: keyPair.algorithm,
            createdAt: new Date(),
        };
    }

    /**
     * Resolve a DID to its DID Document
     */
    async resolveDID(did: string): Promise<DIDResolutionResult> {
        // Validate DID format
        if (!did.startsWith('did:key:')) {
            return {
                didDocument: null,
                didResolutionMetadata: { error: 'invalidDid' },
                didDocumentMetadata: {},
            };
        }

        const multibaseKey = did.replace('did:key:', '');

        // Create verification method ID
        const verificationMethodId = `${did}#${multibaseKey}`;

        // Build DID Document
        const didDocument: DIDDocument = {
            '@context': [
                'https://www.w3.org/ns/did/v1',
                'https://w3id.org/security/suites/ed25519-2020/v1',
            ],
            id: did,
            verificationMethod: [
                {
                    id: verificationMethodId,
                    type: 'Ed25519VerificationKey2020',
                    controller: did,
                    publicKeyMultibase: multibaseKey,
                },
            ],
            authentication: [verificationMethodId],
            assertionMethod: [verificationMethodId],
        };

        return {
            didDocument,
            didResolutionMetadata: { contentType: 'application/did+ld+json' },
            didDocumentMetadata: { created: new Date().toISOString() },
        };
    }

    /**
     * Sign data with DID's private key
     */
    async signWithDID(data: string, didKeyPair: DIDKeyPair): Promise<string> {
        // Decrypt private key
        const privateKey = decrypt(didKeyPair.encryptedPrivateKey, this.encryptionKey);

        // Sign the data
        return sign(data, privateKey);
    }

    /**
     * Verify a signature against a DID
     */
    async verifySignature(data: string, signature: string, did: string, publicKey: string): Promise<boolean> {
        return verify(data, signature, publicKey);
    }

    /**
     * Create a Verifiable Presentation
     */
    async createPresentation(
        credentials: any[],
        didKeyPair: DIDKeyPair,
        domain?: string,
        challenge?: string
    ): Promise<any> {
        const presentation = {
            '@context': ['https://www.w3.org/2018/credentials/v1'],
            type: ['VerifiablePresentation'],
            holder: didKeyPair.did,
            verifiableCredential: credentials,
        };

        // Create proof
        const proofData = {
            ...presentation,
            domain,
            challenge,
            created: new Date().toISOString(),
        };

        const proof = {
            type: 'Ed25519Signature2020',
            created: new Date().toISOString(),
            verificationMethod: `${didKeyPair.did}#${toMultibase(didKeyPair.publicKey)}`,
            proofPurpose: 'authentication',
            domain,
            challenge,
            proofValue: await this.signWithDID(JSON.stringify(proofData), didKeyPair),
        };

        return {
            ...presentation,
            proof,
        };
    }

    /**
     * Get DID from public key
     */
    getDIDFromPublicKey(publicKey: string): string {
        const multibaseKey = toMultibase(publicKey);
        return `did:key:${multibaseKey}`;
    }

    /**
     * Hash credential for on-chain anchoring
     */
    hashCredential(credential: any): string {
        const canonical = JSON.stringify(credential, Object.keys(credential).sort());
        return sha256(canonical);
    }
}

