    const docs = getUserDocuments(userId);
    const verifiedDocs = docs.filter(d => d.verified);

    return {
        verified: verifiedDocs.length > 0,
        documentCount: verifiedDocs.length,
        types: verifiedDocs.map(d => d.type)
    };
}

