import { generateAccessToken, validateAccessToken, sha256 } from './crypto-utils';

/**
 * QR Code Service for CredVerse Wallet
 * Generates time-limited QR codes for credential sharing
 */

export interface QRPayload {
    credentialId: string;
    credentialHash: string;
    accessToken: string;
    verifyEndpoint: string;
    expiry: Date;
    disclosedFields?: string[];
}

export interface QRGenerationOptions {
    expiryMinutes: 1 | 5 | 30 | 60;
    disclosedFields?: string[];
    verifyEndpoint?: string;
}

export interface ShareLink {
    id: string;
    credentialId: string;
    token: string;
    expiry: Date;
    disclosedFields: string[];
    createdAt: Date;
    accessLog: AccessLogEntry[];
}

export interface AccessLogEntry {
    timestamp: Date;
    ip: string;
    userAgent: string;
    location?: string;
    organization?: string;
}

// In-memory storage for share links (production would use database)
const shareLinks = new Map<string, ShareLink>();

/**
 * QR Code Service
 */
export class QRService {
    private baseUrl: string;

    constructor() {
        this.baseUrl = process.env.WALLET_BASE_URL || 'http://localhost:5002';
    }

    /**
     * Generate QR payload for a credential
     */
    generateQRPayload(
        credentialId: string,
        credentialData: any,
        options: QRGenerationOptions
    ): QRPayload {
        const credentialHash = sha256(JSON.stringify(credentialData));

        const { token, expiry } = generateAccessToken(
            {
                credentialId,
                credentialHash,
                disclosedFields: options.disclosedFields || [],
            },
            options.expiryMinutes
        );

        return {
            credentialId,
            credentialHash,
            accessToken: token,
            verifyEndpoint: options.verifyEndpoint || `${this.baseUrl}/api/share/verify`,
            expiry,
            disclosedFields: options.disclosedFields,
        };
    }

    /**
     * Generate a shareable link for a credential
     */
    createShareLink(
        credentialId: string,
        credentialData: any,
        options: QRGenerationOptions
    ): ShareLink {
        const { token, expiry } = generateAccessToken(
            {
                credentialId,
                credentialHash: sha256(JSON.stringify(credentialData)),
                disclosedFields: options.disclosedFields || [],
            },
            options.expiryMinutes
        );

        const shareId = `share-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

        const shareLink: ShareLink = {
            id: shareId,
            credentialId,
            token,
            expiry,
            disclosedFields: options.disclosedFields || [],
            createdAt: new Date(),
            accessLog: [],
        };

        shareLinks.set(shareId, shareLink);
        return shareLink;
    }

    /**
     * Validate and get share link data
     */
    validateShareLink(shareId: string, accessInfo?: Partial<AccessLogEntry>): {
        valid: boolean;
        expired?: boolean;
        shareLink?: ShareLink;
        error?: string;
    } {
        const shareLink = shareLinks.get(shareId);

        if (!shareLink) {
            return { valid: false, error: 'Share link not found' };
        }

        if (new Date() > shareLink.expiry) {
            return { valid: false, expired: true, error: 'Share link expired' };
        }

        // Log access
        if (accessInfo) {
            shareLink.accessLog.push({
                timestamp: new Date(),
                ip: accessInfo.ip || 'unknown',
                userAgent: accessInfo.userAgent || 'unknown',
                location: accessInfo.location,
                organization: accessInfo.organization,
            });
        }

        return { valid: true, shareLink };
    }

    /**
     * Get access log for a share link
     */
    getAccessLog(shareId: string): AccessLogEntry[] {
        const shareLink = shareLinks.get(shareId);
        return shareLink?.accessLog || [];
    }

    /**
     * Revoke a share link
     */
    revokeShareLink(shareId: string): boolean {
        return shareLinks.delete(shareId);
    }

    /**
     * Get all active share links for a credential
     */
    getActiveShareLinks(credentialId: string): ShareLink[] {
        const now = new Date();
        return Array.from(shareLinks.values())
            .filter(link => link.credentialId === credentialId && link.expiry > now);
    }

    /**
     * Generate QR code data URL (using simple SVG)
     */
    generateQRCodeSVG(data: string, size: number = 200): string {
        // This is a placeholder - in production use 'qrcode' npm package
        // For MVP, we'll return the data as a simple encoded format
        const encoded = Buffer.from(JSON.stringify(data)).toString('base64');

        // Return a simple QR-like SVG with the encoded data
        return `data:image/svg+xml,${encodeURIComponent(`
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}">
        <rect width="${size}" height="${size}" fill="white"/>
        <text x="50%" y="50%" dominant-baseline="middle" text-anchor="middle" font-size="10">
          QR: ${encoded.slice(0, 20)}...
        </text>
      </svg>
    `)}`;
    }
}

export const qrService = new QRService();

/**
 * Selective Disclosure Service for CredVerse Wallet
 * Implements field-level disclosure for credentials
 */

export interface SelectiveDisclosureRequest {
    credentialId: string;
    requestedFields: string[];
    requesterDID?: string;
    purpose: string;
    expiryMinutes?: number;
}

export interface DisclosureToken {
    id: string;
    credentialId: string;
    disclosedData: Record<string, any>;
    hiddenFields: string[];
    proof: {
        type: string;
        created: string;
        disclosureDigest: string;
    };
    expiry: Date;
    requesterDID?: string;
    purpose: string;
}

export interface ConsentLog {
    id: string;
    credentialId: string;
    disclosedFields: string[];
    requesterDID?: string;
    requesterName?: string;
    purpose: string;
    timestamp: Date;
    consentGiven: boolean;
    ipAddress?: string;
    userAgent?: string;
}

// In-memory storage
const disclosureTokens = new Map<string, DisclosureToken>();
const consentLogs: ConsentLog[] = [];

/**
 * Selective Disclosure Service
 */
export class SelectiveDisclosureService {
    /**
     * Check if a field path exists in an object
     */
    private getFieldValue(obj: any, path: string): any {
        const parts = path.split('.');
        let current = obj;

        for (const part of parts) {
            if (current === undefined || current === null) return undefined;
            current = current[part];
        }

        return current;
    }

    /**
     * Set a field value in an object using dot notation path
     */
    private setFieldValue(obj: any, path: string, value: any): void {
        const parts = path.split('.');
        let current = obj;

        for (let i = 0; i < parts.length - 1; i++) {
            if (!(parts[i] in current)) {
                current[parts[i]] = {};
            }
            current = current[parts[i]];
        }

        current[parts[parts.length - 1]] = value;
    }

    /**
     * Get all field paths from a credential
     */
    getCredentialFields(credentialData: any): string[] {
        const fields: string[] = [];

        const traverse = (obj: any, prefix: string = '') => {
            for (const key in obj) {
                const path = prefix ? `${prefix}.${key}` : key;

                if (typeof obj[key] === 'object' && obj[key] !== null && !Array.isArray(obj[key])) {
                    traverse(obj[key], path);
                } else {
                    fields.push(path);
                }
            }
        };

        traverse(credentialData);
        return fields;
    }

    /**
     * Create a selective disclosure token
     */
    createDisclosureToken(
        credentialId: string,
        fullCredentialData: any,
        request: SelectiveDisclosureRequest
    ): DisclosureToken {
        const allFields = this.getCredentialFields(fullCredentialData);
        const disclosedData: Record<string, any> = {};
        const hiddenFields: string[] = [];

        // Separate disclosed and hidden fields
        for (const field of allFields) {
            if (request.requestedFields.includes(field)) {
                const value = this.getFieldValue(fullCredentialData, field);
                this.setFieldValue(disclosedData, field, value);
            } else {
                hiddenFields.push(field);
            }
        }

        // Create disclosure digest (hash of what's being disclosed)
        const disclosureDigest = this.hashDisclosure(disclosedData);

        const token: DisclosureToken = {
            id: `disclosure-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
            credentialId,
            disclosedData,
            hiddenFields,
            proof: {
                type: 'SelectiveDisclosure2023',
                created: new Date().toISOString(),
                disclosureDigest,
            },
            expiry: new Date(Date.now() + (request.expiryMinutes || 30) * 60 * 1000),
            requesterDID: request.requesterDID,
            purpose: request.purpose,
        };

        disclosureTokens.set(token.id, token);
        return token;
    }

    /**
     * Log user consent for disclosure
     */
    logConsent(
        credentialId: string,
        disclosedFields: string[],
        consentGiven: boolean,
        metadata: {
            requesterDID?: string;
            requesterName?: string;
            purpose: string;
            ipAddress?: string;
            userAgent?: string;
        }
    ): ConsentLog {
        const log: ConsentLog = {
            id: `consent-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
            credentialId,
            disclosedFields,
            requesterDID: metadata.requesterDID,
            requesterName: metadata.requesterName,
            purpose: metadata.purpose,
            timestamp: new Date(),
            consentGiven,
            ipAddress: metadata.ipAddress,
            userAgent: metadata.userAgent,
        };

        consentLogs.push(log);
        return log;
    }

    /**
     * Get consent history for a credential
     */
    getConsentHistory(credentialId: string): ConsentLog[] {
        return consentLogs
            .filter(log => log.credentialId === credentialId)
            .sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());
    }

    /**
     * Validate a disclosure token
     */
    validateDisclosureToken(tokenId: string): {
        valid: boolean;
        expired?: boolean;
        token?: DisclosureToken;
        error?: string;
    } {
        const token = disclosureTokens.get(tokenId);

        if (!token) {
            return { valid: false, error: 'Token not found' };
        }

        if (new Date() > token.expiry) {
            return { valid: false, expired: true, error: 'Token expired' };
        }

        return { valid: true, token };
    }

    /**
     * Revoke a disclosure token
     */
    revokeDisclosureToken(tokenId: string): boolean {
        return disclosureTokens.delete(tokenId);
    }

    /**
     * Hash the disclosed data for integrity verification
     */
    private hashDisclosure(data: any): string {
        const crypto = require('crypto');
        const canonical = JSON.stringify(data, Object.keys(data).sort());
        return crypto.createHash('sha256').update(canonical).digest('hex');
    }

    /**
     * Common credential field categories for UI
     */
    getFieldCategories(): Record<string, string[]> {
        return {
            'Basic Identity': [
                'credentialSubject.name',
                'credentialSubject.givenName',
                'credentialSubject.familyName',
                'credentialSubject.id',
            ],
            'Contact Information': [
                'credentialSubject.email',
                'credentialSubject.phone',
                'credentialSubject.address',
            ],
            'Academic': [
                'credentialSubject.degree',
                'credentialSubject.degreeName',
                'credentialSubject.major',
                'credentialSubject.graduationDate',
                'credentialSubject.gpa',
                'credentialSubject.honors',
            ],
            'Employment': [
                'credentialSubject.employer',
                'credentialSubject.jobTitle',
                'credentialSubject.startDate',
                'credentialSubject.endDate',
                'credentialSubject.department',
            ],
            'Verification': [
                'issuer',
                'issuanceDate',
                'expirationDate',
                'credentialStatus',
            ],
        };
    }

    /**
     * Suggest minimum required fields for common purposes
     */
    getSuggestedFieldsForPurpose(purpose: string): string[] {
        const purposeFields: Record<string, string[]> = {
            'employment_verification': [
                'credentialSubject.name',
                'credentialSubject.degree',
                'credentialSubject.graduationDate',
                'issuer',
            ],
            'background_check': [
                'credentialSubject.name',
                'credentialSubject.id',
                'issuer',
                'issuanceDate',
            ],
            'academic_record': [
                'credentialSubject.name',
                'credentialSubject.degree',
                'credentialSubject.major',
                'credentialSubject.gpa',
                'credentialSubject.graduationDate',
            ],
            'identity_proof': [
                'credentialSubject.name',
                'credentialSubject.id',
            ],
        };

        return purposeFields[purpose] || ['credentialSubject.name', 'issuer'];
    }
}

