import {
  type User, type InsertUser,
  type Credential, type InsertCredential,
  type Activity, type InsertActivity
} from "@shared/schema";
import { PostgresStateStore } from "@credverse/shared-auth";

export interface IStorage {
  // User
  getUser(id: number): Promise<User | undefined>;
  getUserByUsername(username: string): Promise<User | undefined>;
  createUser(user: InsertUser): Promise<User>;
  updateUser(id: number, user: Partial<InsertUser>): Promise<User>;

  // Credentials
  getCredential(id: number): Promise<Credential | undefined>;
  listCredentials(userId: number): Promise<Credential[]>;
  createCredential(credential: InsertCredential): Promise<Credential>;

  // Activities
  listActivities(userId: number): Promise<Activity[]>;
  createActivity(activity: InsertActivity): Promise<Activity>;
}

interface WalletStorageState {
  users: Array<[number, User]>;
  credentials: Array<[number, Credential]>;
  activities: Array<[number, Activity]>;
  currentUserId: number;
  currentCredentialId: number;
  currentActivityId: number;
}

function parseDate(value: unknown): Date {
  if (value instanceof Date) return value;
  if (typeof value === "string" || typeof value === "number") {
    const date = new Date(value);
    if (!Number.isNaN(date.getTime())) return date;
  }
  return new Date();
}

export class MemStorage implements IStorage {
  private users: Map<number, User>;
  private credentials: Map<number, Credential>;
  private activities: Map<number, Activity>;
  private currentUserId: number;
  private currentCredentialId: number;
  private currentActivityId: number;

  constructor() {
    this.users = new Map();
    this.credentials = new Map();
    this.activities = new Map();
    this.currentUserId = 1;
    this.currentCredentialId = 1;
    this.currentActivityId = 1;
  }

  // User
  async getUser(id: number): Promise<User | undefined> {
    return this.users.get(id);
  }

  async getUserByUsername(username: string): Promise<User | undefined> {
    return Array.from(this.users.values()).find(
      (user) => user.username === username,
    );
  }

  async createUser(insertUser: InsertUser): Promise<User> {
    const id = this.currentUserId++;
    const user: User = {
      ...insertUser,
      id,
      did: insertUser.did ?? null,
      name: insertUser.name ?? null,
      email: insertUser.email ?? null,
      bio: insertUser.bio ?? null,
      avatarUrl: insertUser.avatarUrl ?? null
    };
    this.users.set(id, user);
    return user;
  }

  async updateUser(id: number, updates: Partial<InsertUser>): Promise<User> {
    const user = await this.getUser(id);
    if (!user) throw new Error("User not found");

    const updatedUser = { ...user, ...updates };
    this.users.set(id, updatedUser);
    return updatedUser;
  }

  // Credentials
  async getCredential(id: number): Promise<Credential | undefined> {
    return this.credentials.get(id);
  }

  async listCredentials(userId: number): Promise<Credential[]> {
    return Array.from(this.credentials.values()).filter(
      (c) => c.userId === userId && !c.isArchived
    );
  }

  async createCredential(insertCredential: InsertCredential): Promise<Credential> {
    const id = this.currentCredentialId++;
    const credential: Credential = {
      ...insertCredential,
      id,
      jwt: insertCredential.jwt ?? null,
      isArchived: insertCredential.isArchived ?? false
    };
    this.credentials.set(id, credential);
    return credential;
  }

  // Activities
  async listActivities(userId: number): Promise<Activity[]> {
    return Array.from(this.activities.values())
      .filter((a) => a.userId === userId)
      .sort((a, b) => (b.timestamp?.getTime() ?? 0) - (a.timestamp?.getTime() ?? 0));
  }

  async createActivity(insertActivity: InsertActivity): Promise<Activity> {
    const id = this.currentActivityId++;
    const activity: Activity = {
      ...insertActivity,
      id,
      timestamp: new Date()
    };
    this.activities.set(id, activity);
    return activity;
  }

  exportState(): WalletStorageState {
    return {
      users: Array.from(this.users.entries()),
      credentials: Array.from(this.credentials.entries()),
      activities: Array.from(this.activities.entries()),
      currentUserId: this.currentUserId,
      currentCredentialId: this.currentCredentialId,
      currentActivityId: this.currentActivityId,
    };
  }

  importState(state: WalletStorageState): void {
    this.users = new Map((state.users || []).map(([key, value]) => [key, value]));
    this.credentials = new Map((state.credentials || []).map(([key, value]) => [key, {
      ...value,
      issuanceDate: parseDate((value as any).issuanceDate),
    }]));
    this.activities = new Map((state.activities || []).map(([key, value]) => [key, {
      ...value,
      timestamp: parseDate((value as any).timestamp),
    }]));
    this.currentUserId = state.currentUserId || 1;
    this.currentCredentialId = state.currentCredentialId || 1;
    this.currentActivityId = state.currentActivityId || 1;
  }
}

const requirePersistentStorage =
  process.env.NODE_ENV === "production" || process.env.REQUIRE_DATABASE === "true";
const databaseUrl = process.env.DATABASE_URL;

if (requirePersistentStorage && !databaseUrl) {
  throw new Error(
    "[Storage] REQUIRE_DATABASE policy is enabled but DATABASE_URL is missing."
  );
}

function createPersistedStorage(base: MemStorage, dbUrl?: string): MemStorage {
  if (!dbUrl) {
    return base;
  }

  const stateStore = new PostgresStateStore<WalletStorageState>({
    databaseUrl: dbUrl,
    serviceKey: "wallet-storage",
  });

  let hydrated = false;
  let hydrationPromise: Promise<void> | null = null;
  let persistChain = Promise.resolve();
  const mutatingPrefixes = ["create", "update", "delete", "revoke", "bulk"];

  const ensureHydrated = async () => {
    if (hydrated) return;
    if (!hydrationPromise) {
      hydrationPromise = (async () => {
        const loaded = await stateStore.load();
        if (loaded) {
          base.importState(loaded);
        } else {
          await stateStore.save(base.exportState());
        }
        hydrated = true;
      })();
    }
    await hydrationPromise;
  };

  const queuePersist = async () => {
    persistChain = persistChain
      .then(async () => {
        await stateStore.save(base.exportState());
      })
      .catch((error) => {
        console.error("[Storage] Failed to persist wallet state:", error);
      });
    await persistChain;
  };

  return new Proxy(base, {
    get(target, prop, receiver) {
      const value = Reflect.get(target, prop, receiver);
      if (typeof value !== "function") {
        return value;
      }

      return async (...args: unknown[]) => {
        await ensureHydrated();
        const result = await value.apply(target, args);
        const shouldPersist = mutatingPrefixes.some(
          (prefix) => typeof prop === "string" && prop.startsWith(prefix),
        );
        if (shouldPersist) {
          await queuePersist();
        }
        return result;
      };
    },
  }) as MemStorage;
}

export const storage = createPersistedStorage(new MemStorage(), databaseUrl);

import { pgTable, text, serial, integer, boolean, timestamp, jsonb, uuid, decimal, varchar } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

export const users = pgTable("users", {
  id: serial("id").primaryKey(),
  username: text("username").notNull().unique(),
  password: text("password").notNull(),
  did: text("did"),
  name: text("name"),
  email: text("email"),
  bio: text("bio"),
  avatarUrl: text("avatar_url"),
});

export const credentials = pgTable("credentials", {
  id: serial("id").primaryKey(),
  userId: integer("user_id").notNull(), // Foreign key to users
  type: jsonb("type").notNull(), // Array of types, e.g., ["VerifiableCredential", "UniversityDegree"]
  issuer: text("issuer").notNull(),
  issuanceDate: timestamp("issuance_date").notNull(),
  data: jsonb("data").notNull(), // The credential subject data
  jwt: text("jwt"), // The raw VC-JWT
  isArchived: boolean("is_archived").default(false),
});

export const activities = pgTable("activities", {
  id: serial("id").primaryKey(),
  userId: integer("user_id").notNull(),
  type: text("type").notNull(), // "receive", "share", "connect"
  description: text("description").notNull(),
  timestamp: timestamp("timestamp").defaultNow(),
});

// Claims table - PRD v3.1 Feature 2
export const claims = pgTable("claims", {
  id: serial("id").primaryKey(),
  claimantUserId: integer("claimant_user_id").notNull(),
  platformId: varchar("platform_id", { length: 255 }),
  claimType: varchar("claim_type", { length: 50 }), // insurance_auto, refund_request, age_verification
  claimAmount: decimal("claim_amount", { precision: 12, scale: 2 }),
  description: text("description"),
  timeline: jsonb("timeline"), // Array of {event, time, location}
  evidenceIds: jsonb("evidence_ids"), // Array of evidence IDs
  identityScore: integer("identity_score"),
  integrityScore: integer("integrity_score"),
  authenticityScore: integer("authenticity_score"),
  trustScore: integer("trust_score"),
  recommendation: varchar("recommendation", { length: 20 }), // approve, review, investigate, reject
  redFlags: jsonb("red_flags"),
  aiAnalysis: jsonb("ai_analysis"),
  processingTimeMs: integer("processing_time_ms"),
  createdAt: timestamp("created_at").defaultNow(),
  processedAt: timestamp("processed_at"),
});

// Evidence table - PRD v3.1 Layer 3
export const evidence = pgTable("evidence", {
  id: serial("id").primaryKey(),
  userId: integer("user_id").notNull(),
  claimId: integer("claim_id"),
  mediaType: varchar("media_type", { length: 20 }), // image, video, document
  storageUrl: text("storage_url"),
  authenticityScore: integer("authenticity_score"),
  isAiGenerated: boolean("is_ai_generated"),
  manipulationDetected: boolean("manipulation_detected"),
  metadata: jsonb("metadata"), // EXIF data
  blockchainHash: varchar("blockchain_hash", { length: 66 }),
  analysisData: jsonb("analysis_data"),
  uploadedAt: timestamp("uploaded_at").defaultNow(),
  analyzedAt: timestamp("analyzed_at"),
});

export const insertUserSchema = createInsertSchema(users).pick({
  username: true,
  password: true,
  did: true,
  name: true,
  email: true,
  bio: true,
  avatarUrl: true,
});

export const insertCredentialSchema = createInsertSchema(credentials).pick({
  userId: true,
  type: true,
  issuer: true,
  issuanceDate: true,
  data: true,
  jwt: true,
  isArchived: true,
});

export const insertActivitySchema = createInsertSchema(activities).pick({
  userId: true,
  type: true,
  description: true,
});

export const insertClaimSchema = createInsertSchema(claims).pick({
  claimantUserId: true,
  platformId: true,
  claimType: true,
  claimAmount: true,
  description: true,
  timeline: true,
  evidenceIds: true,
});

export const insertEvidenceSchema = createInsertSchema(evidence).pick({
  userId: true,
  claimId: true,
  mediaType: true,
  storageUrl: true,
  metadata: true,
});

export type InsertUser = z.infer<typeof insertUserSchema>;
export type User = typeof users.$inferSelect;

export type InsertCredential = z.infer<typeof insertCredentialSchema>;
export type Credential = typeof credentials.$inferSelect;

export type InsertActivity = z.infer<typeof insertActivitySchema>;
export type Activity = typeof activities.$inferSelect;

export type InsertClaim = z.infer<typeof insertClaimSchema>;
export type Claim = typeof claims.$inferSelect;

export type InsertEvidence = z.infer<typeof insertEvidenceSchema>;
export type Evidence = typeof evidence.$inferSelect;
